const items = $input.all();
const validRows = [];
const rejectedRows = [];

for (const item of items) {
  const data = item.json;
  if (!data.Vehicle_Model || !data.Year || !data.Region || typeof data.Total_Revenue !== 'number') {
    rejectedRows.push(item);
  } else {
    validRows.push(item);
  }
}

return validRows;

const items = $input.all();
const aggregates = {};

for (const item of items) {
  const { Region, Year, Sales_Volume, Total_Revenue: Revenue, Price_USD } = item.json;
  const key = `${Region}_${Year}`;

  if (!aggregates[key]) {
    aggregates[key] = { Region, Year, total_revenue: 0, total_units: 0, avg_price_sum: 0, count: 0 };
  }

  aggregates[key].total_revenue += Revenue || 0;
  aggregates[key].total_units += Sales_Volume || 0;
  aggregates[key].avg_price_sum += Price_USD || 0;
  aggregates[key].count += 1;
}

const kpiTable = Object.values(aggregates).map(agg => ({
  Region: agg.Region,
  Year: agg.Year,
  total_revenue: agg.total_revenue,
  total_units: agg.total_units,
  average_price: agg.count > 0 ? agg.avg_price_sum / agg.count : 0
}));

const total_revenue = kpiTable.reduce((s, r) => s + r.total_revenue, 0);
const years = kpiTable.map(r => Number(r.Year)).filter(y => !isNaN(y));
const date_range = years.length ? Math.min(...years) + '-' + Math.max(...years) : 'n/a';
const rejected_rows = $('Get row(s) in sheet').all().length - items.length;

const byRev = kpiTable.slice().sort((a, b) => b.total_revenue - a.total_revenue);
const byPrice = kpiTable.slice().sort((a, b) => b.average_price - a.average_price);
const mk = (r, metric) => r ? { metric, region_or_year: r.Region + ' ' + r.Year, value: r[metric], source_row_reference: r.Region + ' + ' + r.Year } : null;
const picks = [mk(byRev[0], 'total_revenue'), mk(byRev[byRev.length - 1], 'total_revenue'), mk(byPrice[0], 'average_price')];

return [{ json: { kpiTable, total_revenue, rejected_rows, date_range, picks } }];

