const item = $input.first();
let output;
try {
  output = typeof (item.json.message && item.json.message.content) === 'string' ? JSON.parse(item.json.message.content) : item.json.message.content;
} catch (e) {
  output = {
    date_range: "n/a", total_revenue: null, rejected_rows: null,
    insights: [{ metric: "insufficient data", value: null, region_or_year: "n/a" }],
    recommended_action: { target_region: "n/a", target_year: "n/a", metric: "insufficient data", rationale_value: null, action: "insufficient data" }
  };
}
return [{ json: output }];

// Mode: Run Once for All Items
const item = $input.first();
const d = item ? item.json : {};

let kpiTable = Array.isArray(d.kpiTable) ? d.kpiTable : [];
if (kpiTable.length === 0) {
  try {
    kpiTable = $('Aggregate KPI Table').first().json.kpiTable || [];
  } catch (e) {
    kpiTable = [];
  }
}

const esc = s => String(s === undefined || s === null ? '' : s)
  .replace(/&/g, '&amp;').replace(/</g, '&lt;')
  .replace(/>/g, '&gt;').replace(/"/g, '&quot;');

const isNum = n => typeof n === 'number' && isFinite(n);

function commas(n, dec) {
  const fixed = Number(n).toFixed(dec);
  const parts = fixed.split('.');
  parts[0] = parts[0].replace(/\B(?=(\d{3})+(?!\d))/g, ',');
  return parts.join('.');
}

const num = (n, dec = 0) => isNum(n) ? commas(n, dec) : 'n/a';
const usd = (n, dec = 0) => isNum(n) ? '$' + commas(n, dec) : 'n/a';

const labels = {
  total_revenue: 'Total revenue',
  average_price: 'Average listed price'
};
const label = m => labels[m] || esc(m || 'metric');
const fmt = (metric, n) => metric === 'average_price' ? usd(n, 2) : usd(n);

const rows = kpiTable
  .map(r => ({ ...r, Year: Number(r.Year) }))
  .sort((a, b) => String(a.Region).localeCompare(String(b.Region)) || a.Year - b.Year);

const years = rows.map(r => r.Year).filter(y => isFinite(y));
const dateRange = years.length ? Math.min(...years) + '–' + Math.max(...years) : 'n/a';

const kpiRows = rows.map(r =>
  '<tr><td>' + esc(r.Region) + '</td><td>' + esc(r.Year) + '</td>' +
  '<td align="right">' + usd(r.total_revenue) + '</td>' +
  '<td align="right">' + num(r.total_units) + '</td>' +
  '<td align="right">' + usd(r.average_price, 2) + '</td></tr>'
).join('\n');

const insights = (Array.isArray(d.insights) ? d.insights : []).map(i =>
  '<li><b>' + esc(label(i.metric)) + '</b>: ' + esc(i.region_or_year) +
  ' — ' + (i.value === null || i.value === undefined ? 'n/a' : fmt(i.metric, i.value)) +
  (i.source_row_reference ? ' <i>(' + esc(i.source_row_reference) + ')</i>' : '') +
  '</li>'
).join('\n');

const ra = d.recommended_action || {};

const action = String(ra.action || 'No action generated.').replace(/_/g, ' ');

const html =
'<h2>Weekly BMW Sales Business Summary</h2>\n' +
'<p><b>Date range:</b> ' + esc(dateRange) + '<br>' +
'<b>Total revenue:</b> ' + usd(d.total_revenue) + '<br>' +
'<b>Rejected rows:</b> ' + num(d.rejected_rows) + '</p>\n' +
'<h3>Key insights</h3>\n<ul>\n' + insights + '\n</ul>\n' +
'<h3>Recommended action</h3>\n' +
'<p>' + esc(action) + '</p>\n' +
'<p><b>Target:</b> ' + esc(ra.target_region) + ' ' + esc(ra.target_year) +
' &nbsp;|&nbsp; <b>' + esc(label(ra.metric)) + ':</b> ' + fmt(ra.metric, ra.rationale_value) + '</p>\n' +
'<h3>KPI table (Region + Year)</h3>\n' +
'<table border="1" cellpadding="5" style="border-collapse:collapse;font-size:13px;">\n' +
'<tr><th>Region</th><th>Year</th><th>Total revenue</th><th>Total units</th><th>Average listed price</th></tr>\n' +
(kpiRows || '<tr><td colspan="5">No KPI rows received. Check that Build Email is connected to Parse &amp; Fallback.</td></tr>') +
'\n</table>';

return [{ json: { html, kpi_row_count: rows.length } }];
